        """Add a line to the order.

        An existing line with the same SKU and unit price has its quantity
        increased instead, so the same product never appears twice. Otherwise a
        new line is appended. Returns the line that was created or updated.
        """
        for line in self.lines:
            if line.sku == sku and line.unit_cents == unit_cents:
                line.qty += qty
